reg [1:0] reg_mem1_state;
always@(posedge sw_clk or negedge rstn)
begin
if(!rstn) begin
 wr_reg_mem1_ack <= 0; 
 rd_reg_mem1_dv  <= 0;
 reg_mem1_state  <= 2'd0;
end else begin
 case(reg_mem1_state) 
 0:begin
     reg_mem1_state <= 2'd0;
     wr_reg_mem1_ack <= 0; 
     rd_reg_mem1_dv <= 0;
     
     if(wr_reg_mem1_dv) begin
       regm.write_reg_mem(wr_reg_mem1_data , wr_reg_mem1_addr, wr_reg_mem1_bytes, wr_reg_mem1_strb); 
	   // $display(" write_reg_mem: wr_reg_mem1_addr %0h wr_reg_mem1_data %0h wr_reg_mem1_bytes %0h wr_reg_mem1_strb %0h",wr_reg_mem1_addr,wr_reg_mem1_data,wr_reg_mem1_bytes,wr_reg_mem1_strb);
       wr_reg_mem1_ack <= 1;
       reg_mem1_state  <= 1;
     end
     if(rd_reg_mem1_req) begin
       regm.read_reg_mem(rd_reg_mem1_data,rd_reg_mem1_addr, rd_reg_mem1_bytes); 
       rd_reg_mem1_dv <= 1;
       reg_mem1_state <= 1;
     end

   end
 1:begin
       rd_reg_mem1_dv  <= 0;
       wr_reg_mem1_ack <= 0;
       reg_mem1_state  <= 0;
   end 
 endcase
end /// if
end// always

