       wr_reg_mem11_ack <= 1;
       reg_mem11_state  <= 1;
     end
     if(rd_reg_mem11_req) begin
       regm.read_reg_mem(rd_reg_mem11_data,rd_reg_mem11_addr, rd_reg_mem11_bytes); 
       rd_reg_mem11_dv <= 1;
       reg_mem11_state <= 1;
     end

   end
 1:begin
       rd_reg_mem11_dv  <= 0;
       wr_reg_mem11_ack <= 0;
       reg_mem11_state  <= 0;
   end 
 endcase
end /// if
end// always

reg [1:0] reg_mem12_state;
always@(posedge sw_clk or negedge rstn)
begin
if(!rstn) begin
 wr_reg_mem12_ack <= 0; 
 rd_reg_mem12_dv  <= 0;
 reg_mem12_state  <= 2'd0;
end else begin
 case(reg_mem12_state) 
 0:begin
     reg_mem12_state <= 2'd0;
     wr_reg_mem12_ack <= 0; 
     rd_reg_mem12_dv <= 0;
     
     if(wr_reg_mem12_dv) begin
       regm.write_reg_mem(wr_reg_mem12_data , wr_reg_mem12_addr, wr_reg_mem12_bytes, wr_reg_mem12_strb); 
	   // $display(" write_reg_mem: wr_reg_mem12_addr %0h wr_reg_mem12_data %0h wr_reg_mem12_bytes %0h wr_reg_mem12_strb %0h",wr_reg_mem12_addr,wr_reg_mem12_data,wr_reg_mem12_bytes,wr_reg_mem12_strb);
       wr_reg_mem12_ack <= 1;
       reg_mem12_state  <= 1;
     end
     if(rd_reg_mem12_req) begin
       regm.read_reg_mem(rd_reg_mem12_data,rd_reg_mem12_addr, rd_reg_mem12_bytes); 
       rd_reg_mem12_dv <= 1;
       reg_mem12_state <= 1;
     end

   end
 1:begin
       rd_reg_mem12_dv  <= 0;
       wr_reg_mem12_ack <= 0;
       reg_mem12_state  <= 0;
   end 
 endcase
end /// if
end// always


