/*****************************************************************************
 * File : versal_cips_ps_vip_v1_0_14_ocmc.sv
 *
 * Date : 2015-16
 *
 * Description : Controller for OCM model
 *
 *****************************************************************************/
 `timescale 1ns/1ps

module versal_cips_ps_vip_v1_0_14_ocmc (
 rstn,
 sw_clk,

/* Goes to port 0 of OCM */
 wr_ack,
 wr_dv,
 rd_req,
 rd_dv,
 wr_addr,
 wr_data,
 wr_strb,
 wr_bytes,
 rd_addr,
 rd_data,
 rd_bytes,
 wr_qos,
 rd_qos

);

`include "versal_cips_ps_vip_v1_0_14_local_params.sv"
input rstn;
input sw_clk;

output wr_ack;
input wr_dv;
input rd_req;
output rd_dv;
input[addr_width-1:0] wr_addr;
input[max_reg_burst_bits-1:0] wr_data;
input[max_reg_burst_bytes-1:0] wr_strb;
input[max_reg_burst_bytes_width:0] wr_bytes;
input[addr_width-1:0] rd_addr;
output[max_reg_burst_bits-1:0] rd_data;
input[max_reg_burst_bytes_width:0] rd_bytes;
input [axi_qos_width-1:0] wr_qos;
input [axi_qos_width-1:0] rd_qos;

wire [axi_qos_width-1:0] wr_qos;
wire wr_req;
wire [max_reg_burst_bits-1:0] wr_data;
wire [max_reg_burst_bytes-1:0] wr_strb;
wire [addr_width-1:0] wr_addr;
wire [max_reg_burst_bytes_width:0] wr_bytes;
reg wr_ack;

wire [axi_qos_width-1:0] rd_qos;
reg [max_reg_burst_bits-1:0] rd_data;
wire [addr_width-1:0] rd_addr;
wire [max_reg_burst_bytes_width:0] rd_bytes;
reg rd_dv;
wire rd_req;

versal_cips_ps_vip_v1_0_14_ocm_mem ocm();

reg [1:0] state;
always@(posedge sw_clk or negedge rstn)
begin
if(!rstn) begin
 wr_ack <= 0; 
 rd_dv <= 0;
 state <= 2'd0;
end else begin
 case(state) 
 0:begin
     state <= 0;
     wr_ack <= 0;
     rd_dv <= 0;
     if(wr_dv) begin
       ocm.write_mem(wr_data , wr_addr, wr_bytes, wr_strb); 
	   // $display(" ocm_write_data wr_addr %0h wr_data %0h wr_bytes %0h wr_strb %0h",wr_addr,wr_data,wr_bytes,wr_strb);
       wr_ack <= 1;
       state <= 1;
     end
     if(rd_req) begin
       ocm.read_mem(rd_data,rd_addr, rd_bytes); 
	   // $display(" ocm_read_data rd_addr %0h rd_data %0h rd_bytes %0h ",rd_addr,rd_data,rd_bytes);
       rd_dv <= 1;
       state <= 1;
     end

   end
 1:begin
       wr_ack <= 0;
       rd_dv  <= 0;
       state <= 0;
   end 

 endcase
end /// if
end// always

endmodule 


/************************************************************************
 * File : versal_cips_ps_vip_v1_0_14_gen_reset.sv
 *
 * Date : 2015-16
 *
 * Description : Module that generates FPGA_RESETs and synchronizes RESETs to the
 *               respective clocks.
 *****************************************************************************/
 `timescale 1ns/1ps
module versal_cips_ps_vip_v1_0_14_gen_reset(
 versal_cips_ps_clk,
 rst_out_n,

 fclk_reset3_n,
 fclk_reset2_n,
 fclk_reset1_n,
 fclk_reset0_n
);

input versal_cips_ps_clk;

output bit rst_out_n;
output fclk_reset3_n;
output fclk_reset2_n;
output fclk_reset1_n;
output fclk_reset0_n;

bit [3:0] fabric_rst_n;
bit por_rst_n;

assign fclk_reset0_n = fabric_rst_n[0];
assign fclk_reset1_n = fabric_rst_n[1];
assign fclk_reset2_n = fabric_rst_n[2];
assign fclk_reset3_n = fabric_rst_n[3];

task pl_gen_reset;
input[3:0] reset_ctrl;
 begin 
  fabric_rst_n[0] = reset_ctrl[0];
  fabric_rst_n[1] = reset_ctrl[1];
  fabric_rst_n[2] = reset_ctrl[2];
  fabric_rst_n[3] = reset_ctrl[3];
  
 end
endtask

task por_reset;
input por_reset_ctrl;
begin 
   por_rst_n = por_reset_ctrl;
end
endtask

always@(posedge versal_cips_ps_clk or negedge por_rst_n )
begin 
   if (!por_rst_n )
      rst_out_n = 1'b0;
   else
      rst_out_n = 1'b1;
end

always@(*) begin
  if ((por_rst_n!= 1'b0) && (por_rst_n!= 1'b1) ) begin
     $display(" ERROR: [VERSAL_CIPS_PS_VIP] (%m) :: [%0d] ::: POR reset must be driven to known state",$time);
     $finish();
  end
end

endmodule


