// ============================================================================
// XILINX custom address decoder for CCI500
// - Combinatorial transaction address decode
// ============================================================================

module versal_cips_ps_vip_cci_address_decode #(parameter
  ADDR_WIDTH       = 44,  // Width of the physical address
  ADDRMAP_WIDTH    = 27,  // Must be 27 for the example address map
  NUM_MI           =  6,  // Total number of master interfaces
  NUM_MI_MEM       =  4,  // Number of memory master interfaces
  SI_NUMBER        =  0,  // Indicates the slave interface number this decoder is connected to
  WRITE_NOT_READ   =  0   // Indicates whether this is a read or write address decoder, high for write
) (
// ACS_off LSB_NON_ZERO Indicates which bits of whole address field are used
  input  wire [ADDR_WIDTH-1:7]     addr_i,      // input address
  input  wire [ADDRMAP_WIDTH-1:0]  addrmap_in,   // configuration input, sampled at reset
  input  wire [2:0]                config_in,   // configuration input, sampled at reset
  input  wire [1:0]                rsvd_i,      // reserved, do not use this input
  output wire [NUM_MI-1:0]         route_z1h_o, // decode output: 1-hot for a valid address, 0 for an invalid address
  output wire                      decerr_o     // set to 1 for an invalid address
);


  // ===================================================================================================================================
  // Decode regions
  // Decode the PCIe/DDR/RESERVED areas. The rest will be sent to core switch
  // ===================================================================================================================================
    wire[4:0] err_region;
    wire[5:0] ddr_region;
    wire[2:0] pci_region;
	reg[25:0] addrmap_i;

//initial begin
 always @(config_in) begin
 case(config_in)
   3'b000  : begin
    addrmap_i = {3'b000,1'b0,3'b000,1'b0,3'b000,1'b0,3'b000,1'b0,3'b000,1'b0,3'b000,1'b0,1'b0};
   end
   3'b001  : begin
    addrmap_i = {3'b001,1'b0,3'b001,1'b0,3'b001,1'b0,3'b001,1'b0,3'b001,1'b0,3'b001,1'b0,1'b0};
   end
   3'b010  : begin
    addrmap_i = {3'b010,1'b0,3'b010,1'b0,3'b010,1'b0,3'b010,1'b0,3'b010,1'b0,3'b010,1'b0,1'b0};
   end
   3'b011  : begin
    addrmap_i = {3'b011,1'b0,3'b011,1'b0,3'b011,1'b0,3'b011,1'b0,3'b011,1'b0,3'b011,1'b0,1'b0};
   end
   3'b100  : begin
    addrmap_i = {3'b100,1'b0,3'b100,1'b0,3'b100,1'b0,3'b100,1'b0,3'b100,1'b0,3'b100,1'b0,1'b0};
   end
   3'b101  : begin
    addrmap_i = {3'b101,1'b0,3'b101,1'b0,3'b101,1'b0,3'b101,1'b0,3'b101,1'b0,3'b101,1'b0,1'b0};
   end
   default : begin
    addrmap_i = {3'b000,1'b0,3'b000,1'b0,3'b000,1'b0,3'b000,1'b0,3'b000,1'b0,3'b000,1'b0,1'b0};
   end
 endcase  
 end


    // PCIe SPACE DECODE
    assign pci_region[0] = (addr_i[ADDR_WIDTH-1:32] == {(ADDR_WIDTH-32){1'b0}}) & (addr_i[31:28] == 4'hE);
  //  assign pci_region[1] = (addr_i[ADDR_WIDTH-1:35] == {(ADDR_WIDTH-35){1'b0}}) & ((addr_i[34:32] == 3'b110) | (addr_i[34:32] == 3'b111));
    assign pci_region[1] = (addr_i[ADDR_WIDTH-1:35] == {(ADDR_WIDTH-35){1'b0}}) & (addr_i[34:33] == 2'b11);
    assign pci_region[2] = (addr_i[ADDR_WIDTH-1:40] == {(ADDR_WIDTH-40){1'b0}}) & (addr_i[39:38] == 2'b10);

    
   
    // RESERVED SPACE DECODE - results in decerr response
    assign err_region[0] = (addr_i[ADDR_WIDTH-1:32] == {(ADDR_WIDTH-32){1'b0}}) & ((addr_i[31:28] == 4'hA) & !(|addr_i[27:26])); 

    assign err_region[1] = (addr_i[ADDR_WIDTH-1:32] == {(ADDR_WIDTH-32){1'b0}}) & ((addr_i[31:28] == 4'hF) & 
	                                                                         (((addr_i[27:24] == 4'h9) & (addr_i[23:20] != 4'h0)) |
										   (addr_i[27:24] == 4'hA)));

    assign err_region[2] = (addr_i[ADDR_WIDTH-1:33] == {(ADDR_WIDTH-33){1'b0}}) & (addr_i[32]== 1'b1) & |(addr_i[31:29]);
    //assign err_region[2] = (addr_i[ADDR_WIDTH-1:34] == {(ADDR_WIDTH-34){1'b0}}) & |(addr_i[33:32]);
    assign err_region[3] = (addr_i[ADDR_WIDTH-1:34] == {(ADDR_WIDTH-34){1'b0}}) & (addr_i[33:32]==2'b11);

    assign err_region[4] = (addr_i[ADDR_WIDTH-1:39] == {(ADDR_WIDTH-39){1'b0}}) & (addr_i[38:36] != 3'd0);

    // Let the NMU decode this - add to ddr region 2. Better for timing.
    ////assign err_region[4] = (addr_i[ADDR_WIDTH-1:40] == {{(ADDR_WIDTH-41){1'b0}}, 1'b1}) & ((&addr_i[40:38]) | (addr_i[40:31] == 10'h36F) | (addr_i[40:35] == 6'h37));


    // DDR/NoC SPACE DECODE
    assign ddr_region[0] =  (addr_i[ADDR_WIDTH-1:31] == {(ADDR_WIDTH-31){1'b0}});

    assign ddr_region[1] = (addr_i[ADDR_WIDTH-1:33] == {(ADDR_WIDTH-33){1'b0}}) & ((addr_i[32] == 1'b1) & (addr_i[31:29] == 3'b0));

    assign ddr_region[2] = (addr_i[ADDR_WIDTH-1:34] == {(ADDR_WIDTH-34){1'b0}}) & (addr_i[33:32] == 2'b10);

    assign ddr_region[3] = (addr_i[ADDR_WIDTH-1:36] == {(ADDR_WIDTH-36){1'b0}}) & (addr_i[35] == 1'b1);

    // Combine region 2,3 since NMU does decode of reserved space on our behalf. Will give better timing. Updating Decoder logic due to EDT-985044
 // assign ddr_region[4] = (addr_i[ADDR_WIDTH-1:42] == {(ADDR_WIDTH-42){1'b0}}) & (|(addr_i[41:40]) | (addr_i[41:38] == 4'h3));
    assign ddr_region[4] = (addr_i[ADDR_WIDTH-1:41] == {(ADDR_WIDTH-41){1'b0}}) & ((addr_i[40]) | (addr_i[39:38] == 2'h3));

    assign ddr_region[5] = addr_i[43] | (addr_i[42] & (|addr_i[41:40]));

//Updating Decoder logic due to EDT-985044
    assign ddr_region_m2_m4 = (addr_i[ADDR_WIDTH-1:42] == {(ADDR_WIDTH-42){1'b0}}) & (addr_i[41:40] == 2'b10);
    assign ddr_region_m3_m5 = (addr_i[ADDR_WIDTH-1:42] == {(ADDR_WIDTH-42){1'b0}}) & (addr_i[41:40] == 2'b11);


  // ===================================================================================================================================
  // Consolidate on 4 decode regions.
  // Decode PCI, DDR and ERR regions explicitly. All the rest goes to "SYS" (core switch)
  // ===================================================================================================================================
  wire dec_is_pci = |pci_region;
  wire dec_is_ddr = |ddr_region;
  wire dec_is_err = |err_region;
  wire dec_is_sys = !(|{dec_is_pci, dec_is_ddr, dec_is_err,ddr_region_m2_m4,ddr_region_m3_m5});

  wire ax_m0 = dec_is_sys;
  wire ax_m1 = dec_is_pci;

  assign decerr_o = dec_is_err;

  // ===================================================================================================================================
  // DDR/NOC Striping decisions
  // ===================================================================================================================================
  wire [2:0] stripe_resolution [0:6];
  wire       stripe_m2m3 [0:6];
  wire       stripe_m4m5 [0:5];

  // Figure out Stripe bits encoding
  wire stripe_all = ~addrmap_i[0] ;

  assign stripe_m2m3[0] = (!stripe_all & ~addrmap_i[1]);
  assign stripe_m2m3[1] = (!stripe_all & ~addrmap_i[5]);
  assign stripe_m2m3[2] = (!stripe_all & ~addrmap_i[9]);
  assign stripe_m2m3[3] = (!stripe_all & ~addrmap_i[13]);
  assign stripe_m2m3[4] = (!stripe_all & ~addrmap_i[17]);
  assign stripe_m2m3[5] = (!stripe_all & ~addrmap_i[21]);
  assign stripe_m2m3[6] = (!stripe_all & ~addrmap_i[1]);

  assign stripe_m4m5[0] = (!stripe_all &  addrmap_i[1]);
  assign stripe_m4m5[1] = (!stripe_all &  addrmap_i[5]);
  assign stripe_m4m5[2] = (!stripe_all &  addrmap_i[9]);
  assign stripe_m4m5[3] = (!stripe_all &  addrmap_i[13]);
  assign stripe_m4m5[4] = (!stripe_all &  addrmap_i[17]);
  assign stripe_m4m5[5] = (!stripe_all &  addrmap_i[21]);
  
  assign stripe_resolution[0] = {addrmap_i[4:2]};
  assign stripe_resolution[1] = {addrmap_i[8:6]};
  assign stripe_resolution[2] = {addrmap_i[12:10]};
  assign stripe_resolution[3] = {addrmap_i[16:14]};
  assign stripe_resolution[4] = {addrmap_i[20:18]};
  assign stripe_resolution[5] = {addrmap_i[24:22]};
  assign stripe_resolution[6] = {addrmap_i[4:2]};
  
  reg ax_ddr0_stripe;
  reg ax_ddr1_stripe;
  reg ax_ddr2_stripe;
  reg ax_ddr3_stripe;

  always_comb
    begin
      if (stripe_all)
        begin
	  case (stripe_resolution[SI_NUMBER])
	  // case (config_in)
	    // 4KB
	    3'b000  : begin
	                ax_ddr0_stripe = ((dec_is_ddr & (addr_i[13:12] == 2'b00)) | ddr_region_m2_m4); 
	                ax_ddr1_stripe = ((dec_is_ddr & (addr_i[13:12] == 2'b01)) | ddr_region_m3_m5); 
	                ax_ddr2_stripe = (dec_is_ddr & (addr_i[13:12] == 2'b10)); 
	                ax_ddr3_stripe = (dec_is_ddr & (addr_i[13:12] == 2'b11)); 
		      end
	    // 2KB
	    3'b001  : begin
	                ax_ddr0_stripe = ((dec_is_ddr & (addr_i[12:11] == 2'b00)) | ddr_region_m2_m4); 
	                ax_ddr1_stripe = ((dec_is_ddr & (addr_i[12:11] == 2'b01)) | ddr_region_m3_m5); 
	                ax_ddr2_stripe = (dec_is_ddr & (addr_i[12:11] == 2'b10)); 
	                ax_ddr3_stripe = (dec_is_ddr & (addr_i[12:11] == 2'b11)); 
		      end
	    // 1KB
	    3'b010  : begin
	                ax_ddr0_stripe = ((dec_is_ddr & (addr_i[11:10] == 2'b00)) | ddr_region_m2_m4); 
	                ax_ddr1_stripe = ((dec_is_ddr & (addr_i[11:10] == 2'b01)) | ddr_region_m3_m5); 
	                ax_ddr2_stripe = (dec_is_ddr & (addr_i[11:10] == 2'b10)); 
	                ax_ddr3_stripe = (dec_is_ddr & (addr_i[11:10] == 2'b11)); 
		      end
	    // 512
	    3'b011  : begin
	                ax_ddr0_stripe = ((dec_is_ddr & (addr_i[10:9] == 2'b00)) | ddr_region_m2_m4); 
	                ax_ddr1_stripe = ((dec_is_ddr & (addr_i[10:9] == 2'b01)) | ddr_region_m3_m5); 
	                ax_ddr2_stripe = (dec_is_ddr & (addr_i[10:9] == 2'b10)); 
	                ax_ddr3_stripe = (dec_is_ddr & (addr_i[10:9] == 2'b11)); 
		      end       
	    // 256
	    3'b100  : begin
	                ax_ddr0_stripe = ((dec_is_ddr & (addr_i[9:8] == 2'b00)) | ddr_region_m2_m4); 
