 task automatic set_routing_config;
    input 	[8191:0] 	destination_port_name;
    input 	[8191:0] 	source_port_name;
    input			routing_en;

    begin
       if(destination_port_name      == master_port0)	master_port_index = 0;
       else if(destination_port_name == master_port1)	master_port_index = 1;
       else if(destination_port_name == master_port2)	master_port_index = 2;
       else if(destination_port_name == master_port3)	master_port_index = 3;
       else if(destination_port_name == master_port4)	master_port_index = 4;
       else if(destination_port_name == master_port5)	master_port_index = 5;
       else if(destination_port_name == master_port6)	master_port_index = 6;
       else if(destination_port_name == master_port7)	master_port_index = 7;
       else if(destination_port_name == master_port8)	master_port_index = 8;
       else if(destination_port_name == master_port9)	master_port_index = 9;
       else if(destination_port_name == master_port11)	master_port_index = 11;
       else if(destination_port_name == master_port12)	master_port_index = 12;
       else if((destination_port_name == master_port10) || (destination_port_name == "OCM") || (destination_port_name == "REG") || (destination_port_name == "PSCPMCFG"))	master_port_index = 10;

       if(source_port_name == slave_port0)		slave_port_index = 0;
       else if(source_port_name == slave_port1)		slave_port_index = 1;
       else if(source_port_name == slave_port2)		slave_port_index = 2;
       else if(source_port_name == slave_port3)		slave_port_index = 3;
       else if(source_port_name == slave_port4)		slave_port_index = 4;
       else if(source_port_name == slave_port5)		slave_port_index = 5;
       else if(source_port_name == slave_port6)		slave_port_index = 6;
       else if(source_port_name == slave_port7)		slave_port_index = 7;
       else if(source_port_name == slave_port8)		slave_port_index = 8;
       else if(source_port_name == slave_port9)		slave_port_index = 9;
       else if(source_port_name == slave_port10)	slave_port_index = 10;
       else if(source_port_name == slave_port11)	slave_port_index = 11;
       else if(source_port_name == slave_port12)	slave_port_index = 12;
       else if(source_port_name == slave_port13)	slave_port_index = 13;
       else if(source_port_name == slave_port14)	slave_port_index = 14;
       else if(source_port_name == slave_port15)	slave_port_index = 15;

       for(int slave_no = 0; slave_no<NUM_OF_SLAVE_PORTS;slave_no++) begin
          for(int master_no = 0;master_no < NUM_OF_MASTER_PORTS;master_no++) begin
	     //$display(" slave_routing_cfg[%d][%d] = %d, slave_port_index = %d, master_port_index = %d, routing_en = %d",slave_no,master_no,slave_routing_cfg[slave_no][master_no],slave_port_index, master_port_index,routing_en);
             if((slave_routing_cfg[slave_no][master_no] == 1) && ((slave_port_index == slave_no) || (master_port_index == master_no)) && (routing_en == 1)) begin
                $display("[ERROR]: [VERSAL_CIPS_PS_VIP] (%m) :: [set_routing_config] [%0d] ::: Current Routing configuration is conflicting with the previously set routing configuration\n\t Try to reset the previous routing configuration with SOURCE: %0s or DESTINATION: %0s for setting the requested routing configuration SOURCE: %0s\t\tDESTINATION:%0s\n",$time,source_port_name,destination_port_name,source_port_name,destination_port_name);
                get_routing_config();
		$stop;
             end
          end
       end
    
       slave_routing_cfg[slave_port_index][master_port_index] = routing_en;
       master_routing_cfg[master_port_index][slave_port_index] = routing_en;
       
       if(routing_en) begin 
          slave_port[slave_port_index] = source_port_name;
          master_port[master_port_index] = destination_port_name;
       end

       get_routing_config();

    end
 endtask // : set_routing_config

 // For printing the routing configuration information
 task automatic get_routing_config;
    begin
    
    //$display("[INFO]: %0s (%0m) :: [get_routing_config] [%0d] ::: Routing Configured is ",DISP_VIP,$time);

    $display("\n--------------------------------------------------------------------------------------------------------");
    $display("                           Routing Configuration ");
    $display("---------------------------------------------------------------------------------------------------------");

    for(int slave_no = 0; slave_no<NUM_OF_SLAVE_PORTS;slave_no++) begin
       for(int master_no = 0;master_no < NUM_OF_MASTER_PORTS;master_no++) begin
          if(slave_routing_cfg[slave_no][master_no] == 1) begin
             $display("   SOURCE: %0s \t\t\t DESTINATION: %0s \t\t Routing ENABLED",slave_port[slave_no],master_port[master_no]);
          end
       end
    end
    $display("---------------------------------------------------------------------------------------------------------\n");

    end
 endtask // : get_routing_config

 // For checking the routing configuration information
 task automatic check_routing_config;
    
    bit routing_set = 0;
    begin
    
    for(int slave_no = 0; slave_no<NUM_OF_SLAVE_PORTS;slave_no++) begin
       for(int master_no = 0;master_no < NUM_OF_MASTER_PORTS;master_no++) begin
          if(slave_routing_cfg[slave_no][master_no] == 1) begin
	     routing_set = 1;
	  end
       end
    end
    
    if(routing_set == 0) begin
       $display("[ERROR]: [VERSAL_CIPS_PS_VIP] (%m) [%0d] :: Routing Information should be provided before initiating the traffic ",$time);
       $stop;
    end

    end
 endtask // : check_routing_config

genvar i;

generate
   for(i = 0;i < NUM_OF_MASTER_PORTS; i++) begin
      
      always @(*) begin
         for(int slave_no = 0; slave_no < NUM_OF_SLAVE_PORTS; slave_no++) begin

