   6,  // Total number of master interfaces
   4,  // Number of memory master interfaces
   0,  // Indicates the slave interface number this decoder is connected to
   0   // Indicates whether this is a read or write address decoder, high for write
) i_cci_address_wr_decode (
  .addr_i(addr_wr_wire),      // input address
  .addrmap_in(addrmap_wire),   // configuration input, sampled at reset
  .config_in(local_config_cci_boundary),   // configuration input, sampled at reset
  .rsvd_i(2'd0),      // reserved, do not use this input
  .route_z1h_o(route_z1h_wr_wire), // decode output: 1-hot for a valid address, 0 for an invalid address
  .decerr_o(decerr_wire)     // set to 1 for an invalid address
);

versal_cips_ps_vip_cci_address_decode  #(
  44,  // Width of the physical address
  27,  // Must be 27 for the example address map
