  .addrmap_in(addrmap_wire),   // configuration input, sampled at reset
  .config_in(local_config_cci_boundary),   // configuration input, sampled at reset
  .rsvd_i(2'd0),      // reserved, do not use this input
  .route_z1h_o(route_z1h_rd_wire), // decode output: 1-hot for a valid address, 0 for an invalid address
  .decerr_o(decerr_wire)     // set to 1 for an invalid address
);

